import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"数据、备份与运维","description":"Hearth 如何在本机完成备份、恢复、维护、存储回收、诊断和全局停止，并说明这些动作各自的边界。","frontmatter":{"title":"数据、备份与运维","description":"Hearth 如何在本机完成备份、恢复、维护、存储回收、诊断和全局停止，并说明这些动作各自的边界。","outline":false},"headers":[],"relativePath":"design/operations.md","filePath":"design/operations.md","lastUpdated":1795426969000}'),r={name:"design/operations.md"};function n(i,e,l,c,s,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="数据、备份与运维" tabindex="-1">数据、备份与运维 <a class="header-anchor" href="#数据、备份与运维" aria-label="Permalink to &quot;数据、备份与运维&quot;">​</a></h1><p class="lead">Hearth 是单机控制面：任务、授权和数据都留在本机，不假设有远程节点或第二台设备替你保管状态。运维的目标不是“功能更多”，而是出问题时能看清、能回退、能停止。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>用户应该知道数据在哪里、哪些动作会修改数据、哪些动作只是停止外部副作用。备份、恢复、维护、存储回收和诊断必须是独立入口，不能把“停止”伪装成“删除”，也不能把数据库备份说成完整迁移。</p><p>长期运行要关注资源而不是只看“没有崩溃”。内存、磁盘、缓存、日志、后台任务和临时文件都需要上限和清理规则；健康检查、异常提醒、升级和回滚要覆盖服务、数据库和桌面代理。</p><h2 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>做什么</th><th>不做什么</th></tr></thead><tbody><tr><td>加密备份</td><td>用口令派生密钥，打包 SQLite 与必要元数据</td><td>不包含产物正文、工作区、来源正文和外部附件</td></tr><tr><td>恢复</td><td>在临时数据库执行 schema、完整性与投影校验，失败回滚</td><td>不撤销已经放行的外部动作</td></tr><tr><td>维护</td><td>清理过期审批、租约、桌面命令、截图、配对和临时文件</td><td>不删除任务、记忆或产物</td></tr><tr><td>存储回收</td><td><code>storage:prune</code> 按保留期与 pin 规则回收旧 run 与未引用工具输出</td><td>不删除活跃 run、未结算操作、checkpoint 引用或产物</td></tr><tr><td>诊断</td><td>导出脱敏健康快照和计数</td><td>不包含密钥、绝对路径和环境秘密</td></tr><tr><td>全局停止</td><td>立即停下调度器、待处理审批和桌面会话</td><td>不删除数据；恢复后执行器仍需手动启动</td></tr></tbody></table><p>备份归档和口令要分开保管。忘记口令后归档无法恢复；恢复前会提示当前数据将被替换，并要求再次确认。恢复完成后执行器保持停止，避免旧任务在新数据上自动重放。</p><h2 id="宿主生命周期与就绪" tabindex="-1">宿主生命周期与就绪 <a class="header-anchor" href="#宿主生命周期与就绪" aria-label="Permalink to &quot;宿主生命周期与就绪&quot;">​</a></h2><p>服务启动由 <code>HostKernel</code> 统一管理：</p><ul><li><strong>租约</strong>：数据目录只允许一个宿主写入；<code>hearth.host.lock</code> 记录 PID 与进程创建时间，PID 复用会被判为陈旧锁。</li><li><strong>阶段</strong>：<code>lease → store → operations → runs → tasks → background → ready</code>；<code>/api/health</code> 暴露 <code>phase</code>、<code>step</code>、<code>readyAt</code>、<code>error</code> 和租约信息。</li><li><strong>关闭</strong>：<code>stop()</code> 先切到 <code>draining</code>，停止接收新任务、取消在跑 run、释放任务租约，最后释放宿主租约。</li><li><strong>就绪门</strong>：恢复完成前 <code>/api/ready</code> 返回 503，创建任务和继续对话的写路由返回 <code>HOST_NOT_READY</code>；只读健康与诊断仍可访问。</li></ul><h2 id="存储回收" tabindex="-1">存储回收 <a class="header-anchor" href="#存储回收" aria-label="Permalink to &quot;存储回收&quot;">​</a></h2><p><code>npm run storage:prune</code> 默认只预演并打印计划，<code>--apply</code> 才实际删除。pin 规则包括：</p><ul><li>保留期内的 run；</li><li>活跃 run 与未结算操作；</li><li>checkpoint 引用的 tool-results；</li><li>已发布产物与任务记录。</li></ul><p>设置页的“数据”分区会显示最近一次回收路径和数量。回收不删除任务、记忆、产物正文或备份归档。</p><h2 id="终态证据与清理" tabindex="-1">终态证据与清理 <a class="header-anchor" href="#终态证据与清理" aria-label="Permalink to &quot;终态证据与清理&quot;">​</a></h2><p>每个终态 run 在任务工作区输出 <code>run-evidence.json</code>，包含 task/run/usage、checkpoint 引用、恢复决策、operations/cleanup、artifacts 与 run 链。物理清理单独记账：</p><ul><li>已登记 shell 进程会被真正终止，结果写回 <code>run_operations</code> 的 cleanup 状态；</li><li>subagent/worktree/browser 等资源暂无 cleanup handler 时明确记 <code>failed</code> 并留下原因；</li><li>后台进程注册表在宿主启动时扫描 <code>running</code> 记录：PID + 创建时间匹配才杀进程树，否则只标 <code>lost</code>，避免误杀复用的 PID。</li></ul><h2 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to &quot;入口&quot;">​</a></h2><p>所有入口都在 <strong>设置 → 数据</strong>：目录结构、SQLite 设置表、迁移记录、回收站、加密备份、恢复、维护、存储回收、脱敏诊断和全局停止。健康状态、任务计数和磁盘占用也在这里汇总，不再保留独立的运维页或安全页。</p>',20)])])}const _=t(r,[["render",n]]);export{u as __pageData,_ as default};
